import { sql } from "drizzle-orm";
import { bigint, char, timestamp, uuid } from "drizzle-orm/pg-core";
import { uuidv7 } from "uuidv7";

// Column conventions (playbook Section 8). Every table uses these, so the rules live in one place:
// - primary keys are UUID v7 (time-ordered, generated by the app)
// - times are UTC timestamptz; screens show IST
// - money is bigint paise with a currency column; never a float
// - soft delete with deleted_at; audit columns record who created and last changed a row

export const id = () =>
  uuid("id")
    .primaryKey()
    .$defaultFn(() => uuidv7());

export const ref = (name: string) => uuid(name);

export const utc = (name: string) => timestamp(name, { withTimezone: true, mode: "date" });

export const timestamps = {
  createdAt: utc("created_at")
    .notNull()
    .default(sql`now()`),
  updatedAt: utc("updated_at")
    .notNull()
    .default(sql`now()`)
    .$onUpdateFn(() => new Date()),
};

export const authorship = {
  createdBy: uuid("created_by"),
  updatedBy: uuid("updated_by"),
};

export const softDelete = {
  deletedAt: utc("deleted_at"),
};

/** An amount in paise (bigint) with its currency. `money("price")` gives price_paise and price_currency. */
export const money = (name: string) => ({
  paise: bigint(`${name}_paise`, { mode: "bigint" }).notNull(),
  currency: char(`${name}_currency`, { length: 3 }).notNull().default("INR"),
});
